const headers = $input.first().json.headers ?? {};
const header = headers['x-assetnest-signature'];
const deliveryId = headers['x-assetnest-delivery'];
const match = typeof header === 'string' && /^t=(\d+),v1=([0-9a-f]{64})$/.exec(header);
if (!match || typeof deliveryId !== 'string' || !deliveryId) throw new Error('Invalid AssetNest headers');
const [, timestamp, providedDigest] = match;
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) throw new Error('AssetNest timestamp outside replay window');

const rawBytes = await this.helpers.getBinaryDataBuffer(0, 'data');
const rawBody = rawBytes.toString('utf8');
// The Crypto node hashes a UTF-8 string. Require an exact byte round trip.
if (!rawBytes.equals(Buffer.from(rawBody, 'utf8'))) throw new Error('Invalid AssetNest body encoding');
return [{ json: { deliveryId, providedDigest, signedBody: timestamp + '.' + rawBody } }];

const { timingSafeEqual } = require('crypto');
const { deliveryId, providedDigest, expectedDigest, signedBody } = $input.first().json;
const isDigest = (value) => typeof value === 'string' && /^[0-9a-f]{64}$/.test(value);
if (!isDigest(providedDigest) || !isDigest(expectedDigest) || !timingSafeEqual(Buffer.from(providedDigest, 'hex'), Buffer.from(expectedDigest, 'hex'))) {
  throw new Error('AssetNest signature mismatch');
}

let body;
try {
  body = JSON.parse(signedBody.slice(signedBody.indexOf('.') + 1));
} catch {
  throw new Error('Invalid AssetNest JSON');
}
if (!body || typeof body.id !== 'string' || typeof body.kind !== 'string') throw new Error('Invalid AssetNest event');
return [{ json: { verified: true, deliveryId, event: body.kind, eventId: body.id, occurredAt: body.occurredAt, workspaceId: body.workspaceId, resourceId: body.resourceId, payload: body.payload } }];
